import { getPosts, getCategories } from '@/lib/graphql';
import type { Metadata } from 'next';
import { getModuleConfig } from '@/lib/templates/config';
import { getTenantCached } from '@/lib/modules';
import BlogLayoutEditorial from '@/components/blog/BlogLayoutEditorial';
import BlogLayoutList from '@/components/blog/BlogLayoutList';
import BlogLayoutMagazine from '@/components/blog/BlogLayoutMagazine';
import BlogLayoutStream from '@/components/blog/BlogLayoutStream';
import BlogLayoutSpotlight from '@/components/blog/BlogLayoutSpotlight';

export const revalidate = 60;
export const metadata: Metadata = { title: 'Blog' };

const blogConfig = getModuleConfig('blog');

const templateMutedText = 'var(--template-muted-text, #6b7280)';

export default async function BlogPage() {
  const tenant = await getTenantCached();
  const savedModules = (tenant?.templateConfig?.modules) as Record<string, Record<string, unknown>> | undefined;
  const savedLayout = ((savedModules?.blog?.layout ?? {}) as Partial<typeof blogConfig.layout>);
  const layoutVariant = (savedLayout.variant as string | undefined) ?? 'editorial';

  let posts: Awaited<ReturnType<typeof getPosts>> = [];
  let categories: Awaited<ReturnType<typeof getCategories>> = [];
  let error: string | null = null;

  try {
    [posts, categories] = await Promise.all([getPosts(), getCategories('blog')]);
  } catch (e) {
    error = e instanceof Error ? e.message : 'Failed to load posts';
  }

  if (error) {
    return (
      <div className="mx-auto max-w-7xl px-4 py-20 text-center sm:px-6" style={{ color: templateMutedText }}>
        <p>{error}</p>
      </div>
    );
  }

  if (posts.length === 0) {
    return (
      <div className="mx-auto max-w-7xl px-4 py-20 text-center sm:px-6" style={{ color: templateMutedText }}>
        No published posts yet.
      </div>
    );
  }

  if (layoutVariant === 'list')      return <BlogLayoutList      posts={posts} categories={categories} />;
  if (layoutVariant === 'magazine')  return <BlogLayoutMagazine  posts={posts} categories={categories} />;
  if (layoutVariant === 'stream')    return <BlogLayoutStream    posts={posts} categories={categories} />;
  if (layoutVariant === 'spotlight') return <BlogLayoutSpotlight posts={posts} categories={categories} />;
  return <BlogLayoutEditorial posts={posts} categories={categories} />;
}

import Link from 'next/link';
import Image from 'next/image';
import type { Recipe } from '@/lib/graphql';
import { resolveMediaUrl } from '@/lib/graphql';

const accent = 'var(--template-accent, #e5201b)';
const ink = 'var(--template-ink, #161218)';
const panelBackground = 'var(--template-panel, #ffffff)';
const panelBorder = 'var(--template-panel-border, #e5e7eb)';

const DIFFICULTY_BADGE: Record<string, { bg: string; color: string }> = {
  easy:   { bg: 'rgba(22,163,74,0.88)',  color: '#fff' },
  medium: { bg: 'rgba(202,138,4,0.90)',  color: '#fff' },
  hard:   { bg: 'rgba(220,38,38,0.88)', color: '#fff' },
};

function formatTime(mins: number | null): string | null {
  if (!mins) return null;
  if (mins < 60) return `${mins}m`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return m ? `${h}h ${m}m` : `${h}h`;
}

/** Clock SVG icon */
function ClockIcon() {
  return (
    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <circle cx="12" cy="12" r="10" />
      <path d="M12 6v6l4 2" />
    </svg>
  );
}

export default function RecipeCard({
  recipe,
  /** compact = tighter padding, used in horizontal scroll strip */
  compact,
}: {
  recipe: Recipe;
  compact?: boolean;
}) {
  const imageUrl = resolveMediaUrl(recipe.coverImage);
  const totalTime = (recipe.prepTime ?? 0) + (recipe.cookTime ?? 0);

  const diff = (recipe.difficulty ?? '').toLowerCase();
  const badge = DIFFICULTY_BADGE[diff];

  return (
    <article
      data-recipe-card
      className="group hover:shadow-xl"
      style={{
        display: 'flex',
        flexDirection: 'column',
        borderRadius: compact ? 14 : 18,
        overflow: 'hidden',
        boxShadow: '0 4px 24px rgba(22,18,24,0.07)',
        transition: 'box-shadow 0.25s',
      }}
    >
      {/* ΓöÇΓöÇ Image wrapper ΓöÇΓöÇ */}
      <div style={{ position: 'relative', aspectRatio: '3 / 2', flexShrink: 0, overflow: 'hidden', background: '#e5e7eb' }}>
        {/* Recipe link covers the whole image */}
        <Link
          href={`/recipes/${recipe.slug}`}
          style={{ position: 'absolute', inset: 0, display: 'block', textDecoration: 'none' }}
          aria-label={recipe.title}
        >
          {imageUrl ? (
            <Image
              src={imageUrl}
              alt={recipe.title}
              fill
              className="object-cover group-hover:scale-105"
              style={{ transition: 'transform 0.5s ease', transformOrigin: 'center' }}
            />
          ) : (
            <div
              style={{
                position: 'absolute', inset: 0,
                background: `linear-gradient(135deg, ${accent}22 0%, ${accent}44 100%)`,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
              }}
            >
              <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke={accent} strokeWidth="1.5" opacity="0.6">
                <path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10 10-4.5 10-10S17.5 2 12 2zm0 5v5l3 2" />
              </svg>
            </div>
          )}

          {/* Bottom gradient for text legibility */}
          <div style={{
            position: 'absolute', inset: 0,
            background: 'linear-gradient(to top, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0.15) 45%, transparent 70%)',
          }} />
        </Link>

        {/* Category pill ΓÇö sibling of image link, positioned bottom-left */}
        {recipe.category && (
          <Link
            data-recipe-category
            href={`/recipes/category/${recipe.category.slug}`}
            style={{
              position: 'absolute', bottom: 10, left: 10,
              padding: '0.2rem 0.6rem',
              borderRadius: 999,
              background: accent,
              color: '#fff',
              fontSize: '0.68rem',
              fontWeight: 800,
              letterSpacing: '0.08em',
              textTransform: 'uppercase',
              textDecoration: 'none',
              zIndex: 2,
            }}
          >
            {recipe.category.name}
          </Link>
        )}

        {/* Difficulty badge ΓÇö top right */}
        {badge && (
          <span data-recipe-difficulty style={{
            position: 'absolute', top: 10, right: 10,
            padding: '0.2rem 0.55rem',
            borderRadius: 999,
            background: badge.bg,
            color: badge.color,
            fontSize: '0.65rem',
            fontWeight: 700,
            textTransform: 'capitalize',
            letterSpacing: '0.04em',
            backdropFilter: 'blur(4px)',
            zIndex: 2,
          }}>
            {recipe.difficulty}
          </span>
        )}
      </div>

      {/* ΓöÇΓöÇ Text body ΓöÇΓöÇ */}
      <div style={{
        padding: compact ? '0.75rem 0.9rem 0.85rem' : '1rem 1.1rem 1.15rem',
        background: panelBackground,
        flex: 1,
        display: 'flex',
        flexDirection: 'column',
        gap: 0,
      }}>
        <h2 style={{
          fontSize: compact ? '0.9rem' : '1.05rem',
          fontWeight: 700,
          lineHeight: 1.25,
          color: ink,
          marginBottom: '0.4rem',
          display: '-webkit-box',
          WebkitLineClamp: 2,
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden',
        }}>
          <Link href={`/recipes/${recipe.slug}`} style={{ color: 'inherit', textDecoration: 'none' }}>
            {recipe.title}
          </Link>
        </h2>

        {recipe.description && !compact && (
          <p style={{
            fontSize: '0.8rem',
            color: ink,
            opacity: 0.6,
            lineHeight: 1.5,
            display: '-webkit-box',
            WebkitLineClamp: 2,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
            marginBottom: '0.5rem',
          }}>
            {recipe.description}
          </p>
        )}

        {totalTime > 0 && (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.3rem',
            marginTop: 'auto',
            paddingTop: '0.4rem',
            fontSize: '0.75rem',
            fontWeight: 600,
            color: ink,
            opacity: 0.45,
          }}>
            <ClockIcon />
            {formatTime(totalTime)}
            {recipe.servings && (
              <>
                <span style={{ opacity: 0.6 }}>┬╖</span>
                <span>{recipe.servings} serv.</span>
              </>
            )}
          </div>
        )}
      </div>
    </article>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import type { Review } from '@/lib/graphql';
import { resolveMediaUrl } from '@/lib/graphql';
import type { ReviewsModuleColors } from '@/lib/templates/config';

const PER_PAGE = 4;

function getScoreTier(score: number) {
  if (score >= 9.5) return 'excellent';
  if (score >= 7.5) return 'great';
  if (score >= 6.1) return 'good';
  if (score >= 4.0) return 'mixed';
  return 'poor';
}

function getVerdict(score: number): string {
  if (score >= 9.5) return 'Universal Acclaim';
  if (score >= 7.5) return 'Generally Favorable';
  if (score >= 6.1) return 'Mostly Positive';
  if (score >= 4.0) return 'Mixed or Average';
  if (score >= 2.0) return 'Generally Unfavorable';
  return 'Overwhelming Dislike';
}

export default function ReviewStrip({
  reviews,
  heading,
  colors,
}: {
  reviews: Review[];
  heading: string;
  colors: ReviewsModuleColors;
}) {
  const sorted = [...reviews].sort((a, b) => {
    const sa = a.rating ? parseFloat(a.rating) : 0;
    const sb = b.rating ? parseFloat(b.rating) : 0;
    return sb - sa;
  });

  const [page, setPage] = useState(0);
  const [fading, setFading] = useState(false);
  const [direction, setDirection] = useState<'left' | 'right'>('right');
  const pendingPage = useRef<number | null>(null);
  const totalPages = Math.ceil(sorted.length / PER_PAGE);
  const visible = sorted.slice(page * PER_PAGE, page * PER_PAGE + PER_PAGE);

  useEffect(() => {
    if (!fading) return;
    const t = setTimeout(() => {
      if (pendingPage.current !== null) {
        setPage(pendingPage.current);
        pendingPage.current = null;
      }
      setFading(false);
    }, 180);
    return () => clearTimeout(t);
  }, [fading]);

  function changePage(next: number, dir: 'left' | 'right') {
    if (fading) return;
    pendingPage.current = next;
    setDirection(dir);
    setFading(true);
  }

  return (
    <section>
      {/* ΓöÇΓöÇ Header row ΓöÇΓöÇ */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
          <div style={{ width: 4, height: 20, background: 'var(--template-accent, #ec0f7f)', flexShrink: 0 }} />
          <h2 style={{
            margin: 0,
            fontSize: '1.15rem',
            fontWeight: 900,
            letterSpacing: '-0.03em',
            color: 'var(--template-ink, #161218)',
          }}>
            {heading}
          </h2>
        </div>

        {/* Arrow buttons */}
        <div style={{ display: 'flex', gap: '0.4rem' }}>
          <button
            onClick={() => changePage(Math.max(0, page - 1), 'left')}
            disabled={page === 0}
            aria-label="Previous"
            style={{
              width: 34, height: 34,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              border: '1px solid var(--template-panel-border, #e5e7eb)',
              background: page === 0 ? 'transparent' : 'var(--template-panel, #fff)',
              color: page === 0 ? 'var(--template-ink, #161218)' : 'var(--template-ink, #161218)',
              opacity: page === 0 ? 0.3 : 1,
              cursor: page === 0 ? 'default' : 'pointer',
              transition: 'opacity 0.15s',
            }}
          >
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
              <path d="M9 2L4 7l5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
          <button
            onClick={() => changePage(Math.min(totalPages - 1, page + 1), 'right')}
            disabled={page >= totalPages - 1}
            aria-label="Next"
            style={{
              width: 34, height: 34,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              border: '1px solid var(--template-panel-border, #e5e7eb)',
              background: page >= totalPages - 1 ? 'transparent' : 'var(--template-panel, #fff)',
              color: 'var(--template-ink, #161218)',
              opacity: page >= totalPages - 1 ? 0.3 : 1,
              cursor: page >= totalPages - 1 ? 'default' : 'pointer',
              transition: 'opacity 0.15s',
            }}
          >
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
              <path d="M5 2l5 5-5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
        </div>
      </div>

      {/* ΓöÇΓöÇ Divider ΓöÇΓöÇ */}
      <div style={{ height: 1, background: 'var(--template-panel-border, #e5e7eb)', marginBottom: '1.1rem' }} />

      {/* ΓöÇΓöÇ Cards ΓöÇΓöÇ */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(4, 1fr)',
        gap: '1rem',
        opacity: fading ? 0 : 1,
        transform: fading
          ? `translateX(${direction === 'right' ? '-12px' : '12px'})`
          : 'translateX(0)',
        transition: 'opacity 0.18s ease, transform 0.18s ease',
      }}>
        {visible.map((review) => {
          const imageUrl = resolveMediaUrl(review.coverImage);
          const score = review.rating ? parseFloat(review.rating) : null;
          const tier = score != null && !Number.isNaN(score) ? getScoreTier(score) : null;
          const palette = tier ? colors.scorePalettes[tier] : null;
          const typeStyle = colors.typeStyles[review.reviewType] ?? colors.typeStyles.other;

          return (
            <article
              key={review.slug}
              data-review-strip-card
              className="group"
              style={{
                display: 'flex',
                flexDirection: 'column',
                background: 'var(--template-panel, #fff)',
                border: '1px solid var(--template-panel-border, #e5e7eb)',
                borderLeft: palette ? `4px solid ${palette.background}` : '4px solid var(--template-panel-border, #e5e7eb)',
                overflow: 'hidden',
              }}
            >
              {/* Image */}
              <Link
                href={`/reviews/${review.slug}`}
                style={{ display: 'block', position: 'relative', aspectRatio: '4 / 3', overflow: 'hidden', flexShrink: 0 }}
              >
                {imageUrl ? (
                  <Image
                    src={imageUrl}
                    alt={review.subject || review.title}
                    fill
                    className="object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                ) : (
                  <div style={{ position: 'absolute', inset: 0, background: 'var(--template-muted-panel, #f3f4f6)' }} />
                )}
              </Link>

              {/* Content */}
              <div style={{ padding: '0.75rem 0.875rem', flex: 1, display: 'flex', flexDirection: 'column', gap: '0.4rem' }}>
                <h3 style={{
                  margin: 0,
                  fontSize: '0.95rem',
                  fontWeight: 900,
                  lineHeight: 1.25,
                  letterSpacing: '-0.02em',
                  color: 'var(--template-ink, #161218)',
                }}>
                  <Link href={`/reviews/${review.slug}`} style={{ color: 'inherit', textDecoration: 'none' }}
                    className="hover:underline">
                    {review.subject || review.title}
                  </Link>
                </h3>

                <span
                  style={{
                    display: 'inline-block',
                    alignSelf: 'flex-start',
                    padding: '0.15rem 0.5rem',
                    fontSize: '0.62rem',
                    fontWeight: 700,
                    letterSpacing: '0.06em',
                    border: '1px solid var(--template-panel-border, #e5e7eb)',
                    color: 'var(--template-ink, #161218)',
                    opacity: 0.7,
                  }}
                >
                  {review.reviewType}
                </span>
              </div>

              {/* Score section */}
              {palette && score != null && (
                <div style={{
                  padding: '0.6rem 0.875rem 0',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: '0.5rem',
                }}>
                  <div>
                    <p style={{ fontSize: '0.55rem', fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase', color: 'var(--template-ink, #161218)', opacity: 0.4, marginBottom: 2 }}>
                      Score
                    </p>
                    <p style={{ fontSize: '0.78rem', fontWeight: 800, color: palette.background, lineHeight: 1.2 }}>
                      {getVerdict(score)}
                    </p>
                  </div>
                  <div
                    data-score-chip
                    data-score-tier={tier}
                    style={{
                      width: 44, height: 44, flexShrink: 0,
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      background: palette.background,
                      color: palette.text,
                      fontWeight: 900,
                      fontSize: '1.2rem',
                      letterSpacing: '-0.03em',
                    }}
                  >
                    {Number.isInteger(score) ? String(score) : score.toFixed(1)}
                  </div>
                </div>
              )}

              {/* Score bar */}
              {palette && score != null && (
                <div style={{ margin: '0.6rem 0.875rem 0.875rem', height: 4, background: 'var(--template-panel-border, #e5e7eb)' }}>
                  <div style={{
                    height: '100%',
                    width: `${(score / 10) * 100}%`,
                    background: palette.background,
                  }} />
                </div>
              )}
            </article>
          );
        })}
      </div>
    </section>
  );
}

/**
 * Links ΓÇö Instagram / Podcast link-in-bio
 *
 * Compact single-column layout. Profile-style hero (image as avatar, headline as
 * name, subtitle as bio). Features rendered as large link buttons. Auto-generated
 * links to each active module. Reviews strip for social proof. No pricing/FAQ/stats.
 */

import type { LandingPage, LandingFeature, LandingTestimonial, LandingLogo } from '@/lib/graphql';
import { resolveMediaUrl } from '@/lib/graphql';
import Image from 'next/image';
import Link from 'next/link';
import { t, FeatureIcon, StarRating, type ModuleData, type Review } from './sections';
import {
  PenTool, Utensils, ShoppingBag, Home, Star, MessageSquare,
} from 'lucide-react';

const MODULE_LINKS: Record<string, { label: string; href: string; Icon: typeof PenTool }> = {
  blog:       { label: 'Blog',        href: '/blog',       Icon: PenTool },
  recipes:    { label: 'Recipes',     href: '/recipes',    Icon: Utensils },
  products:   { label: 'Shop',        href: '/products',   Icon: ShoppingBag },
  realestate: { label: 'Properties',  href: '/properties', Icon: Home },
  reviews:    { label: 'Reviews',     href: '/reviews',    Icon: Star },
};

export default function LandingPageLayoutLinks({ page, modules }: { page: LandingPage; modules: ModuleData }) {
  const heroImage = resolveMediaUrl(page.heroImage);
  const topReviews = modules.reviews.slice(0, 3);
  const activeModuleLinks = modules.activeModules
    .filter((m) => m !== 'landingpage' && MODULE_LINKS[m])
    .map((m) => MODULE_LINKS[m]);

  return (
    <main className="min-h-screen" style={{ background: t.mutedPanel }}>
      <div className="max-w-lg mx-auto px-4 py-12">

        {/* ΓöÇΓöÇ Profile hero ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className="text-center mb-10">
          {heroImage && (
            <div className="relative w-28 h-28 rounded-full overflow-hidden mx-auto mb-5 shadow-lg" style={{ border: `3px solid ${t.accent}` }}>
              <Image src={heroImage} alt={page.heroHeadline || 'Profile'} fill className="object-cover" priority />
            </div>
          )}
          {page.heroBadge && (
            <span className="inline-block mb-2 px-3 py-1 text-[10px] font-bold uppercase tracking-[0.15em] rounded-full" style={{ background: t.accent, color: '#fff' }}>
              {page.heroBadge}
            </span>
          )}
          {page.heroHeadline && (
            <h1 className="text-2xl font-extrabold" style={{ color: t.ink }}>{page.heroHeadline}</h1>
          )}
          {page.heroSubheadline && (
            <p className="mt-2 text-sm leading-relaxed" style={{ color: t.mutedText }}>{page.heroSubheadline}</p>
          )}
          {page.heroBody && (
            <p className="mt-2 text-xs leading-relaxed max-w-xs mx-auto" style={{ color: t.mutedText, opacity: 0.7 }}>{page.heroBody}</p>
          )}

          {/* Primary CTA as a prominent button */}
          {page.heroPrimaryCtaText && (
            <div className="mt-5">
              <Link data-lp-primary-cta href={page.heroPrimaryCtaUrl || '#'} className="inline-block w-full max-w-xs px-6 py-3 font-bold rounded-xl shadow-lg text-center transition-transform hover:scale-105" style={{ background: t.accent, color: '#fff' }}>
                {page.heroPrimaryCtaText}
              </Link>
            </div>
          )}
        </div>

        {/* ΓöÇΓöÇ Features as link buttons ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        {page.features.length > 0 && (
          <div className="flex flex-col gap-3 mb-8">
            {page.features.map((f: LandingFeature) => (
              <Link
                data-lp-feature-link
                key={f.id}
                href={f.linkUrl || '#'}
                className="flex items-center gap-4 px-5 py-4 rounded-xl font-semibold transition-all hover:shadow-md hover:scale-[1.02]"
                style={{ background: t.panel, border: `1px solid ${t.panelBorder}`, color: t.ink }}
              >
                <div className="w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0" style={{ background: t.mutedPanel, color: t.accent }}>
                  <FeatureIcon icon={f.icon} size={20} />
                </div>
                <div className="flex-1 min-w-0">
                  <span className="block truncate">{f.title}</span>
                  {f.description && <span className="block text-xs truncate" style={{ color: t.mutedText }}>{f.description}</span>}
                </div>
                <span style={{ color: t.mutedText }}>ΓåÆ</span>
              </Link>
            ))}
