              Other Locations
            </h2>
          </div>
          <div className="grid gap-3 sm:grid-cols-2">
            {ungrouped.map((l) => <NeighborhoodRow key={l.slug} listing={l} />)}
          </div>
        </section>
      )}
    </div>
  );
}

